'use client'

import { cn } from '@/lib/utils'
import { formatRelativeDate } from '@/lib/payroll/utils'
import type { PayrollRunStatus } from '@/lib/supabase/types'
import { PAYROLL_STEPS } from '@/lib/payroll/constants'

interface TimelineStep {
  key: PayrollRunStatus
  label: string
  ts?: string | null
}

const ORDERED_STEPS: TimelineStep[] = PAYROLL_STEPS.map((s) => ({ key: s.key as PayrollRunStatus, label: s.label }))

type StepState = 'completed' | 'current' | 'pending'

function getStepState(stepKey: PayrollRunStatus, currentStatus: PayrollRunStatus): StepState {
  const order: PayrollRunStatus[] = ['draft', 'calculated', 'approved', 'paid']
  const stepIdx = order.indexOf(stepKey)
  const currentIdx = order.indexOf(currentStatus)

  if (currentStatus === 'cancelled') {
    // Show all steps as completed up to where it was cancelled
    return stepIdx < currentIdx ? 'completed' : 'pending'
  }

  if (stepIdx < currentIdx) return 'completed'
  if (stepIdx === currentIdx) return 'current'
  return 'pending'
}

interface Props {
  status: PayrollRunStatus
  calculatedAt?: string | null
  approvedAt?: string | null
  paidAt?: string | null
  createdAt?: string | null
}

export function PayrollTimeline({ status, createdAt, calculatedAt, approvedAt, paidAt }: Props) {
  const timestamps: Partial<Record<PayrollRunStatus, string | null | undefined>> = {
    draft: createdAt,
    calculated: calculatedAt,
    approved: approvedAt,
    paid: paidAt,
  }

  const steps = ORDERED_STEPS.filter((s) => s.key !== 'cancelled')

  return (
    <div className="payroll-timeline">
      {steps.map((step, idx) => {
        const state = getStepState(step.key, status)
        const ts = timestamps[step.key]
        const isLast = idx === steps.length - 1

        return (
          <div key={step.key} className="payroll-timeline-step">
            <div
              className={cn('payroll-timeline-dot', {
                'payroll-timeline-dot-completed': state === 'completed',
                'payroll-timeline-dot-current':   state === 'current',
                'payroll-timeline-dot-pending':   state === 'pending',
              })}
            />
            {!isLast && (
              <div
                className={cn('payroll-timeline-connector', {
                  'payroll-timeline-connector-done':    state === 'completed',
                  'payroll-timeline-connector-pending': state !== 'completed',
                })}
              />
            )}
            <span
              className={cn('payroll-timeline-step-label', {
                'payroll-timeline-step-label-current': state === 'current',
              })}
            >
              {step.label}
            </span>
            {ts && (
              <span className="payroll-timeline-step-ts">
                {formatRelativeDate(ts)}
              </span>
            )}
          </div>
        )
      })}
    </div>
  )
}

