import { Skeleton } from '@/components/ui/skeleton'
import { PayrollRunStatusBadge } from './PayrollRunStatusBadge'
import { NewRunSheet } from './NewRunSheet'
import { formatCurrency } from '@/lib/utils'
import { formatPeriodMonth, formatRelativeDate, runLabel } from '@/lib/payroll/utils'
import { currentYear } from '@/lib/payroll/utils'
import type { Database } from '@/lib/supabase/types'

type PayrollRun = Database['public']['Tables']['payroll_runs']['Row']

interface Props {
  runs: PayrollRun[] | null
  isLoading?: boolean
  isOwner: boolean
  canManage: boolean
}

export function PayrollRunsTab({ runs, isLoading, isOwner, canManage }: Props) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const [isPending, startTransition] = useTransition()
  const [search, setSearch] = useState('')
  const [sheetOpen, setSheetOpen] = useState(false)
  const [confirmAction, setConfirmAction] = useState<{
    type: 'calculate' | 'approve'
    runId: string
    label: string
  } | null>(null)

  const statusFilter = searchParams.get('status') ?? 'all'
  const yearFilter = searchParams.get('year') ?? String(currentYear())

  const setParam = (key: string, value: string) => {
    const params = new URLSearchParams(searchParams.toString())
    params.set(key, value)
    router.push(`?${params.toString()}`, { scroll: false })
  }

  const clearFilters = () => router.push('?', { scroll: false })

  const executeAction = useCallback(async (type: 'calculate' | 'approve' | 'cancel', runId: string) => {
    const path = type === 'calculate' ? 'calculate' : type === 'approve' ? 'approve' : 'cancel'
    try {
      const res = await fetch(`/api/payroll/runs/${runId}/${path}`, { method: 'POST' })
      if (!res.ok) {
        const body = await res.json().catch(() => ({}))
        throw new Error(body.error ?? 'Request failed')
      }
      toast.success(
        type === 'calculate' ? 'Payroll calculated' :
        type === 'approve'   ? 'Payroll approved' :
                               'Payroll run cancelled',
      )
      startTransition(() => router.refresh())
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Action failed')
    }
  }, [router])

  const filteredRuns = (runs ?? []).filter((r) => {
    if (search) {
      const q = search.toLowerCase()
      const label = runLabel(r.label, r.period_start).toLowerCase()
      if (!label.includes(q) && !r.period_start.includes(q)) return false
    }
    return true
  })

  if (isLoading) {
    return (
      <div className="p-6">
        <Table>
          <TableHeader>
            <TableRow>
              {['Period', 'Status', 'Artists', 'Gross', 'Net', 'Created', ''].map((h) => (
                <TableHead key={h}>{h}</TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {Array.from({ length: 5 }).map((_, i) => (
              <TableRow key={i}>
                <TableCell><Skeleton className="h-4 w-20" /></TableCell>
                <TableCell><Skeleton className="h-5 w-24 rounded-full" /></TableCell>
                <TableCell><Skeleton className="h-4 w-8" /></TableCell>
                <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                <TableCell><Skeleton className="h-4 w-16" /></TableCell>
                <TableCell><Skeleton className="h-7 w-7 rounded-md" /></TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
    )
  }

  return (
    <>
      {/* Toolbar */}
      <div className="flex items-center gap-3 px-6 py-4 border-b border-border">
        <Input
          placeholder="Search by label or period…"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="h-8 text-sm max-w-xs"
        />
        <div className="ml-auto flex items-center gap-2">
          <Select value={statusFilter} onValueChange={(v) => setParam('status', v)}>
            <SelectTrigger className="h-8 text-sm w-36">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All statuses</SelectItem>
              <SelectItem value="draft">Draft</SelectItem>
              <SelectItem value="calculated">Calculated</SelectItem>
              <SelectItem value="approved">Approved</SelectItem>
              <SelectItem value="paid">Paid</SelectItem>
              <SelectItem value="cancelled">Cancelled</SelectItem>
            </SelectContent>
          </Select>
          <Select value={yearFilter} onValueChange={(v) => setParam('year', v)}>
            <SelectTrigger className="h-8 text-sm w-28">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {[currentYear(), currentYear() - 1, currentYear() - 2].map((y) => (
                <SelectItem key={y} value={String(y)}>{y}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Table */}
      {filteredRuns.length === 0 ? (
        (runs ?? []).length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 gap-3">
            <DollarSign className="h-10 w-10 text-muted-foreground/40" />
            <p className="text-sm font-medium text-foreground">No payroll runs</p>
            <p className="text-xs text-muted-foreground max-w-xs text-center">
              Create your first run to pay out approved commissions to your artists.
            </p>
            {canManage && (
              <Button size="sm" className="mt-2" onClick={() => setSheetOpen(true)}>
                <Plus className="h-4 w-4 mr-1.5" />
                New Run
              </Button>
            )}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-16 gap-2">
            <p className="text-sm font-medium text-foreground">No runs match these filters</p>
            <Button variant="ghost" size="sm" onClick={clearFilters}>Clear filters</Button>
          </div>
        )
      ) : (
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Period</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="tabular-nums">Artists</TableHead>
              <TableHead className="tabular-nums">Gross</TableHead>
              <TableHead className="tabular-nums">Net</TableHead>
              <TableHead>Created</TableHead>
              <TableHead className="w-10" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredRuns.map((run) => (
              <TableRow
                key={run.id}
                className="cursor-pointer"
                onClick={() => router.push(`/payroll/runs/${run.id}`)}
              >
                <TableCell>
                  <div className="font-medium text-sm">{formatPeriodMonth(run.period_start)}</div>
                  {run.label && <div className="text-xs text-muted-foreground">{run.label}</div>}
                </TableCell>
                <TableCell>
                  <PayrollRunStatusBadge status={run.status} />
                </TableCell>
                <TableCell className="tabular-nums text-sm">
                  {run.status === 'cancelled' ? '—' : (run.artist_count ?? '—')}
                </TableCell>
                <TableCell className="tabular-nums text-sm">
                  {run.total_gross_cents != null ? formatCurrency(run.total_gross_cents) : '—'}
                </TableCell>
                <TableCell className="tabular-nums text-sm">
                  {run.total_net_cents != null ? formatCurrency(run.total_net_cents) : '—'}
                </TableCell>
                <TableCell className="text-sm text-muted-foreground">
                  {formatRelativeDate(run.created_at)}
                </TableCell>
                <TableCell onClick={(e) => e.stopPropagation()}>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon" className="h-7 w-7">
                        <MoreHorizontal className="h-4 w-4" />
                        <span className="sr-only">Actions</span>
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem onClick={() => router.push(`/payroll/runs/${run.id}`)}>
                        <Eye className="h-4 w-4 mr-2" /> View
                      </DropdownMenuItem>
                      {(run.status === 'draft') && (isOwner || canManage) && (
                        <DropdownMenuItem onClick={() => setConfirmAction({ type: 'calculate', runId: run.id, label: runLabel(run.label, run.period_start) })}>
                          <Calculator className="h-4 w-4 mr-2" /> Calculate
                        </DropdownMenuItem>
                      )}
                      {run.status === 'calculated' && isOwner && (
                        <DropdownMenuItem onClick={() => setConfirmAction({ type: 'approve', runId: run.id, label: runLabel(run.label, run.period_start) })}>
                          <CheckCircle className="h-4 w-4 mr-2" /> Approve
                        </DropdownMenuItem>
                      )}
                      {run.status !== 'paid' && run.status !== 'cancelled' && isOwner && (
                        <DropdownMenuItem
                          className="text-destructive focus:text-destructive"
                          onClick={() => executeAction('cancel', run.id)}
                        >
                          <XCircle className="h-4 w-4 mr-2" /> Cancel
                        </DropdownMenuItem>
                      )}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      )}

      {/* Confirm dialog for calculate / approve */}
      {confirmAction && (
        <AlertDialog open onOpenChange={() => setConfirmAction(null)}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>
                {confirmAction.type === 'calculate' ? 'Calculate payroll?' : 'Approve payroll?'}
              </AlertDialogTitle>
              <AlertDialogDescription>
                {confirmAction.type === 'calculate'
                  ? `This will calculate totals for the "${confirmAction.label}" run. Existing calculations will be overwritten.`
                  : `Approving "${confirmAction.label}" locks totals and allows marking it as paid. This cannot be undone.`}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => {
                  const action = confirmAction
                  setConfirmAction(null)
                  executeAction(action.type, action.runId)
                }}
              >
                {confirmAction.type === 'calculate' ? 'Calculate' : 'Approve'}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}

      {canManage && (
        <NewRunSheet open={sheetOpen} onOpenChange={setSheetOpen} onSuccess={() => startTransition(() => router.refresh())} />
      )}
    </>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import { Calendar, ChevronRight, Loader2, Users } from 'lucide-react'
import {
  Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Skeleton } from '@/components/ui/skeleton'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { formatCurrency } from '@/lib/utils'
import { lastMonthStart, lastMonthEnd } from '@/lib/payroll/utils'

interface Props {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSuccess: () => void
}

interface PreviewArtist {
  artist_id: string
  full_name: string | null
  avatar_url: string | null
  record_count: number
  total_cents: number
}

interface PreviewData {
  artists: PreviewArtist[]
  total_cents: number
  record_count: number
  period_start: string
  period_end: string
}

type Step = 1 | 2 | 3

export function NewRunSheet({ open, onOpenChange, onSuccess }: Props) {
  const [step, setStep] = useState<Step>(1)
  const [periodStart, setPeriodStart] = useState(lastMonthStart())
  const [periodEnd, setPeriodEnd] = useState(lastMonthEnd())
  const [label, setLabel] = useState('')
  const [preview, setPreview] = useState<PreviewData | null>(null)
  const [isPreviewing, setIsPreviewing] = useState(false)
  const [isCreating, startTransition] = useTransition()

  const reset = () => {
    setStep(1)
    setPeriodStart(lastMonthStart())
    setPeriodEnd(lastMonthEnd())
    setLabel('')
    setPreview(null)
  }

  const handleClose = (open: boolean) => {
    if (!open) reset()
    onOpenChange(open)
  }

  const goToStep2 = async () => {
    if (!periodStart || !periodEnd) {
      toast.error('Select both a start and end date')
      return
    }
    if (periodStart >= periodEnd) {
      toast.error('End date must be after start date')
      return
    }
    setIsPreviewing(true)
    try {
      const res = await fetch('/api/payroll/preview', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ period_start: periodStart, period_end: periodEnd }),
      })
      const body = await res.json()
      if (!res.ok) throw new Error(body.error ?? 'Preview failed')
      setPreview(body.data)
      setStep(2)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load preview')
    } finally {
      setIsPreviewing(false)
    }
  }

  const goToStep3 = () => setStep(3)

  const handleCreate = () => {
    startTransition(async () => {
      try {
        const res = await fetch('/api/payroll/runs', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            period_start: periodStart,
            period_end: periodEnd,
            label: label.trim() || null,
          }),
        })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? 'Failed to create run')
        toast.success('Payroll run created')
        handleClose(false)
        onSuccess()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to create payroll run')
      }
    })
  }

  const STEP_LABELS = ['Period', 'Preview', 'Confirm']

  return (
    <Sheet open={open} onOpenChange={handleClose}>
      <SheetContent side="right" className="w-full max-w-lg flex flex-col p-0 gap-0">
        <SheetHeader className="px-6 pt-6 pb-4 border-b border-border shrink-0">
          <SheetTitle className="text-lg font-semibold">New Payroll Run</SheetTitle>
          <SheetDescription className="sr-only">Create a new payroll run for your studio</SheetDescription>
          {/* Step indicator */}
          <div className="flex items-center gap-0 mt-3">
            {STEP_LABELS.map((sl, idx) => {
              const stepNum = (idx + 1) as Step
              const isActive = step === stepNum
              const isDone = step > stepNum
              return (
                <div key={sl} className="flex items-center gap-0 flex-1">
                  <div className="flex flex-col items-center gap-1">
                    <div
                      className={`h-2 w-2 rounded-full transition-colors ${
                        isDone  ? 'bg-[var(--color-payroll-timeline-completed)]' :
                        isActive ? 'bg-primary shadow-[0_0_0_3px_oklch(62%_0.24_292/0.2)]' :
                                   'bg-[var(--color-payroll-timeline-pending)]'
                      }`}
                    />
                    <span className={`text-xs font-medium ${isActive ? 'text-primary' : 'text-muted-foreground'}`}>
                      {sl}
                    </span>
                  </div>
                  {idx < STEP_LABELS.length - 1 && (
                    <div className={`flex-1 h-px mx-2 mt-[-0.8rem] ${isDone ? 'bg-[var(--color-payroll-timeline-completed)]' : 'bg-[var(--color-payroll-timeline-pending)]'}`} />
                  )}
                </div>
              )
            })}
          </div>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto px-6 py-6">
          {/* Step 1: Period selection */}
          {step === 1 && (
            <div className="space-y-5">
              <div className="space-y-1.5">
                <Label htmlFor="period-start">Period start</Label>
                <Input
                  id="period-start"
                  type="date"
                  value={periodStart}
                  onChange={(e) => setPeriodStart(e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="period-end">Period end</Label>
                <Input
                  id="period-end"
                  type="date"
                  value={periodEnd}
                  onChange={(e) => setPeriodEnd(e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="run-label">Label <span className="text-muted-foreground">(optional)</span></Label>
                <Input
                  id="run-label"
                  placeholder="e.g. March 2026"
                  value={label}
                  onChange={(e) => setLabel(e.target.value)}
                  maxLength={80}
                />
                <p className="text-xs text-muted-foreground">
                  If blank, defaults to the period month.
                </p>
              </div>
            </div>
          )}

          {/* Step 2: Preview */}
          {step === 2 && (
            <div className="space-y-4">
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <Calendar className="h-4 w-4" />
                {periodStart} – {periodEnd}
              </div>
              {isPreviewing ? (
                <div className="space-y-2">
                  {Array.from({ length: 4 }).map((_, i) => (
                    <Skeleton key={i} className="h-10 w-full" />
                  ))}
                </div>
              ) : preview && preview.artists.length > 0 ? (
                <>
                  <div className="text-xs text-muted-foreground">
                    {preview.record_count} approved commission{preview.record_count !== 1 ? 's' : ''} · {preview.artists.length} artist{preview.artists.length !== 1 ? 's' : ''}
                  </div>
                  <div className="space-y-2">
                    {preview.artists.map((a) => (
                      <div key={a.artist_id} className="flex items-center gap-3 py-2 border-b border-border/50 last:border-0">
                        <Avatar className="h-7 w-7">
                          <AvatarImage src={a.avatar_url ?? undefined} />
                          <AvatarFallback className="text-xs">{a.full_name?.[0] ?? '?'}</AvatarFallback>
                        </Avatar>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium truncate">{a.full_name ?? 'Unknown'}</p>
                          <p className="text-xs text-muted-foreground">{a.record_count} records</p>
                        </div>
                        <span className="tabular-nums text-sm font-semibold">
                          {formatCurrency(a.total_cents)}
                        </span>
                      </div>
                    ))}
                  </div>
                  <div className="flex items-center justify-between pt-2 border-t border-border">
                    <span className="text-sm font-medium">Total gross</span>
                    <span className="tabular-nums font-bold">{formatCurrency(preview.total_cents)}</span>
                  </div>
                </>
              ) : (
                <div className="flex flex-col items-center justify-center py-12 gap-2 text-center">
                  <Users className="h-8 w-8 text-muted-foreground/40" />
                  <p className="text-sm font-medium">No eligible commissions</p>
                  <p className="text-xs text-muted-foreground max-w-xs">
                    No approved or finalized commissions found in this period that haven&apos;t been included in a previous run.
                  </p>
                </div>
              )}
            </div>
          )}

          {/* Step 3: Confirm */}
          {step === 3 && (
            <div className="space-y-4">
              <p className="text-sm text-muted-foreground">
                Confirm the details below. After creation, use <strong>Calculate</strong> to compute exact totals.
              </p>
              <div className="rounded-lg border border-border bg-card p-4 space-y-3 text-sm">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Period</span>
                  <span className="font-medium">{periodStart} – {periodEnd}</span>
                </div>
                {label && (
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">Label</span>
                    <span className="font-medium">{label}</span>
                  </div>
                )}
                {preview && (
                  <>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Artists eligible</span>
                      <span className="font-medium">{preview.artists.length}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Est. gross total</span>
                      <span className="font-medium tabular-nums">{formatCurrency(preview.total_cents)}</span>
                    </div>
                  </>
                )}
              </div>
              <p className="text-xs text-muted-foreground">
                The run starts in <strong>Draft</strong> status. Calculate it to compute exact totals before approving.
              </p>
            </div>
          )}
        </div>

        {/* Footer actions */}
        <div className="px-6 py-4 border-t border-border shrink-0 flex justify-between gap-3">
          {step > 1 ? (
            <Button variant="outline" size="sm" onClick={() => setStep((s) => (s - 1) as Step)}>
              Back
            </Button>
          ) : (
            <Button variant="outline" size="sm" onClick={() => handleClose(false)}>
              Cancel
            </Button>
          )}

          {step === 1 && (
            <Button size="sm" onClick={goToStep2} disabled={isPreviewing}>
              {isPreviewing ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" /> : null}
              Preview
              <ChevronRight className="h-4 w-4 ml-1" />
            </Button>
          )}
          {step === 2 && (
            <Button size="sm" onClick={goToStep3}>
              Continue
              <ChevronRight className="h-4 w-4 ml-1" />
            </Button>
          )}
          {step === 3 && (
            <Button size="sm" onClick={handleCreate} disabled={isCreating}>
              {isCreating ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" /> : null}
              Create Run
            </Button>
          )}
        </div>
      </SheetContent>
    </Sheet>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import { AlertTriangle, Loader2 } from 'lucide-react'
import {
  Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { PAYMENT_METHODS } from '@/lib/payroll/constants'

interface Props {
  open: boolean
  onOpenChange: (open: boolean) => void
  runId: string
  runLabel: string
  onSuccess: () => void
}

export function MarkPaidModal({ open, onOpenChange, runId, runLabel, onSuccess }: Props) {
  const [paymentMethod, setPaymentMethod] = useState('')
  const [reference, setReference] = useState('')
  const [isPending, startTransition] = useTransition()

  const reset = () => {
    setPaymentMethod('')
    setReference('')
  }

  const handleClose = (open: boolean) => {
    if (!open) reset()
    onOpenChange(open)
  }

  const handleSubmit = () => {
    if (!paymentMethod) {
      toast.error('Select a payment method')
      return
    }
    startTransition(async () => {
      try {
        const res = await fetch(`/api/payroll/runs/${runId}/mark-paid`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            payment_method: paymentMethod,
            payment_reference: reference.trim() || null,
          }),
        })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? 'Failed to mark as paid')
        toast.success('Payroll run marked as paid')
        handleClose(false)
        onSuccess()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to mark run as paid')
      }
    })
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Mark Run as Paid</DialogTitle>
          <DialogDescription>"{runLabel}"</DialogDescription>
        </DialogHeader>

        {/* Warning */}
        <div className="lock-warning">
          <AlertTriangle className="h-4 w-4 mt-0.5 shrink-0" style={{ color: 'var(--color-lock-warning-text)' }} />
          <p className="lock-warning-text">
            Marking a run as paid is permanent. Ensure all artist payments have been sent before proceeding.
            This action cannot be undone.
          </p>
        </div>

        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label>Payment method</Label>
            <Select value={paymentMethod} onValueChange={setPaymentMethod}>
              <SelectTrigger>
                <SelectValue placeholder="Select method…" />
              </SelectTrigger>
              <SelectContent>
                {PAYMENT_METHODS.map((m) => (
                  <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="reference">Reference <span className="text-muted-foreground">(optional)</span></Label>
            <Input
