import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface RouteContext {
  params: Promise<{ id: string }>
}

const MarkPaidSchema = z.object({
  payment_method: z.enum(['check', 'ach', 'cash', 'dodo_connect', 'external', 'other']),
  payment_reference: z.string().max(200).optional().nullable(),
})

export async function POST(req: NextRequest, ctx: RouteContext) {
  const { id } = await ctx.params
  const supabase = await createClient()

  const { data: { user }, error: authErr } = await supabase.auth.getUser()
  if (authErr || !user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No studio membership' }, { status: 403 })

  // mark_payroll_paid is owner-only
  if (member.role !== 'owner') {
    return Response.json({ error: 'Only studio owners can mark payroll runs as paid' }, { status: 403 })
  }

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const guard = requireFeature(plan, 'payroll')
  if (guard) return guard

  const body = MarkPaidSchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { data, error } = await supabase.rpc('mark_payroll_paid', {
    p_run_id: id,
    p_method: body.data.payment_method,
    p_reference: body.data.payment_reference ?? null,
  })
  if (error) {
    logger.error({ err: error, runId: id }, 'mark_payroll_paid failed')
    return Response.json({ error: 'Failed to mark payroll run as paid' }, { status: 500 })
  }

  return Response.json({ data })
}

