  const [voidTarget, setVoidTarget] = useState<string | null>(null)

  const filteredForms = (forms ?? []).filter((f) => String(f.tax_year) === yearFilter)

  const handleGenerate = () => {
    startGenerating(async () => {
      try {
        const res = await fetch('/api/tax-forms/generate-1099k', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ tax_year: parseInt(yearFilter, 10) }),
        })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? 'Generation failed')
        toast.success(`1099-K forms generated for ${yearFilter}`)
        router.refresh()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to generate forms')
      }
    })
  }

  const handleVoid = async (formId: string) => {
    try {
      const res = await fetch(`/api/tax-forms/${formId}/void`, { method: 'POST' })
      const body = await res.json()
      if (!res.ok) throw new Error(body.error ?? 'Void failed')
      toast.success('Form voided')
      router.refresh()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to void form')
    } finally {
      setVoidTarget(null)
    }
  }

  if (isLoading) {
    return (
      <div className="p-6">
        <Table>
          <TableHeader>
            <TableRow>
              {['Artist', 'Gross', 'Txn Count', 'Threshold', 'Status', 'PDF', 'Sent', ''].map((h) => (
                <TableHead key={h}>{h}</TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {Array.from({ length: 5 }).map((_, i) => (
              <TableRow key={i}>
                <TableCell className="flex items-center gap-2"><Skeleton className="h-7 w-7 rounded-full" /><Skeleton className="h-4 w-24" /></TableCell>
                <TableCell><Skeleton className="h-4 w-20" /></TableCell>
                <TableCell><Skeleton className="h-4 w-12" /></TableCell>
                <TableCell><Skeleton className="h-5 w-20 rounded-full" /></TableCell>
                <TableCell><Skeleton className="h-5 w-20 rounded-full" /></TableCell>
                <TableCell><Skeleton className="h-6 w-6 rounded" /></TableCell>
                <TableCell><Skeleton className="h-4 w-16" /></TableCell>
                <TableCell><Skeleton className="h-6 w-6 rounded" /></TableCell>
