        <div className="ml-auto">
          {isJanuary() && canGenerate ? (
            <Button
              size="sm"
              onClick={() => setConfirmGenerate(true)}
              disabled={isGenerating}
            >
              {isGenerating
                ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
                : <Plus className="h-4 w-4 mr-1.5" />
              }
              Generate 1099-Ks for {yearFilter}
            </Button>
          ) : (
            <p className="text-xs text-muted-foreground">
              1099-K forms can only be generated in January.
            </p>
          )}
        </div>
      </div>

      {/* Table or empty state */}
      {filteredForms.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 gap-3">
          <FileBadge className="h-10 w-10 text-muted-foreground/40" />
          <p className="text-sm font-medium">No 1099-K forms yet</p>
          <p className="text-xs text-muted-foreground max-w-xs text-center">
            Generate 1099-K forms in January for artists who earned $600 or more in a calendar year.
            File with the IRS and send to each artist.
          </p>
          {isJanuary() && canGenerate && (
            <Button size="sm" className="mt-2" onClick={() => setConfirmGenerate(true)}>
              Generate 1099-Ks for {currentYear()}
            </Button>
          )}
        </div>
      ) : (
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Artist</TableHead>
              <TableHead className="tabular-nums">Gross</TableHead>
              <TableHead className="tabular-nums">Txn Count</TableHead>
              <TableHead>Threshold</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>PDF</TableHead>
              <TableHead>Sent</TableHead>
              <TableHead className="w-10" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredForms.map((form) => {
              const isBelowThreshold = !form.gross_amount_cents || form.gross_amount_cents < 60_000
              return (
                <TableRow
                  key={form.id}
                  className={`cursor-pointer ${isBelowThreshold ? 'opacity-60' : ''}`}
                  onClick={() => router.push(`/payroll/tax-forms/${form.id}`)}
                >
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Avatar className="h-7 w-7">
                        <AvatarImage src={form.artists?.avatar_url ?? undefined} />
                        <AvatarFallback className="text-xs">{form.artists?.full_name?.[0] ?? '?'}</AvatarFallback>
                      </Avatar>
                      <span className="text-sm font-medium">{form.artists?.full_name ?? '—'}</span>
                    </div>
                  </TableCell>
                  <TableCell className="tabular-nums text-sm">
                    {form.gross_amount_cents != null ? formatCurrency(form.gross_amount_cents) : '—'}
