                  <TableCell>
                    <TaxFormStatusBadge status={form.status} />
                  </TableCell>
                  <TableCell onClick={(e) => e.stopPropagation()}>
                    {form.pdf_storage_path ? (
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-6 w-6"
                        asChild
                      >
                        <a href={`/api/tax-forms/${form.id}/download`} download>
                          <Download className="h-3.5 w-3.5" />
                          <span className="sr-only">Download PDF</span>
                        </a>
                      </Button>
                    ) : (
                      <span className="text-muted-foreground text-sm">—</span>
                    )}
                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">
                    {form.sent_at ? new Date(form.sent_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '—'}
                  </TableCell>
                  <TableCell onClick={(e) => e.stopPropagation()}>
                    {canManage && !form.locked_at && (
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon" className="h-7 w-7">
                            <MoreHorizontal className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => router.push(`/payroll/tax-forms/${form.id}`)}>
                            Review &amp; Send
                          </DropdownMenuItem>
                          {form.status !== 'voided' && (
                            <DropdownMenuItem
                              className="text-destructive focus:text-destructive"
                              onClick={() => setVoidTarget(form.id)}
                            >
                              Void
                            </DropdownMenuItem>
                          )}
                        </DropdownMenuContent>
                      </DropdownMenu>
                    )}
                  </TableCell>
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      )}

      {/* Confirm generate dialog */}
      <AlertDialog open={confirmGenerate} onOpenChange={setConfirmGenerate}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Generate 1099-K forms for {yearFilter}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will create draft 1099-K forms for all artists who earned $600 or more in {yearFilter}.
              Artists below the threshold are skipped. You can review and send each form individually.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => { setConfirmGenerate(false); handleGenerate() }}>
              Generate
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm void dialog */}
      {voidTarget && (
        <AlertDialog open onOpenChange={() => setVoidTarget(null)}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Void this 1099-K form?</AlertDialogTitle>
              <AlertDialogDescription>
                Voiding is permanent. If this form has been sent to the artist, issue a correction instead.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction onClick={() => handleVoid(voidTarget)} className="bg-destructive hover:bg-destructive/90">
                Void Form
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}
    </>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { getUserPermissions } from '@/lib/team/permissions'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import { PayrollHub } from '@/components/payroll/PayrollHub'

export const metadata: Metadata = {
  title: 'Payroll — InkOS',
}

export default async function PayrollPage() {
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) redirect('/onboarding')

  const studioId = member.studio_id
  const role = member.role as string

  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  if (!hasFeature(plan, 'payroll')) {
    return (
      <div className="flex flex-1 items-center justify-center p-8">
        <UpgradeGatePageBlock
          requiredPlan="pro"
          feature="Payroll & 1099-K"
          description="Run payroll, collect W-9s, and generate 1099-K tax forms for your artists. Upgrade to the Pro plan to unlock this feature."
        />
      </div>
    )
  }

  const permissionsSet = await getUserPermissions(studioId, user.id)
  const isOwner = role === 'owner'
  const canManage =
    isOwner ||
    permissionsSet.has('payroll.manage') ||
    permissionsSet.has('admin.all')
  const canGenerate =
    isOwner ||
    permissionsSet.has('tax_forms.generate') ||
    permissionsSet.has('admin.all')

  return (
    <PayrollHub
      studioId={studioId}
      isOwner={isOwner}
      canManage={canManage}
      canGenerate={canGenerate}
    />
  )
}

