import { useEffect } from 'react'
import type { Database } from '@/lib/supabase/types'

type PayrollRun = Database['public']['Tables']['payroll_runs']['Row']
type TaxFormRow = Database['public']['Tables']['tax_forms']['Row'] & {
  artists: { id: string; full_name: string | null; avatar_url: string | null } | null
}

interface ArtistRow {
  artist_id: string
  full_name: string | null
  avatar_url: string | null
  tax_info: Database['public']['Tables']['artist_tax_info']['Row'] | null
}

interface Props {
  studioId: string
  isOwner: boolean
  canManage: boolean
  canGenerate: boolean
}

export function PayrollHub({ studioId, isOwner, canManage, canGenerate }: Props) {
  const router = useRouter()
  const [sheetOpen, setSheetOpen] = useState(false)
  const [isPending, startTransition] = useTransition()

  const [runs, setRuns] = useState<PayrollRun[] | null>(null)
  const [artists, setArtists] = useState<ArtistRow[] | null>(null)
  const [taxForms, setTaxForms] = useState<TaxFormRow[] | null>(null)
  const [loadingRuns, setLoadingRuns] = useState(true)
  const [loadingArtists, setLoadingArtists] = useState(true)
  const [loadingForms, setLoadingForms] = useState(true)

  const loadRuns = async () => {
    setLoadingRuns(true)
    try {
      const res = await fetch('/api/payroll/runs')
      if (!res.ok) throw new Error('Failed')
      const body = await res.json()
      setRuns(body.data ?? [])
    } catch {
      toast.error('Failed to load payroll runs')
      setRuns([])
    } finally {
      setLoadingRuns(false)
    }
  }

  const loadArtists = async () => {
    setLoadingArtists(true)
    try {
      const res = await fetch(`/api/payroll/artists-tax-info?studio_id=${studioId}`)
      if (!res.ok) throw new Error('Failed')
      const body = await res.json()
      setArtists(body.data ?? [])
    } catch {
      setArtists([])
    } finally {
      setLoadingArtists(false)
    }
  }

  const loadForms = async () => {
    setLoadingForms(true)
    try {
      const res = await fetch('/api/tax-forms')
      if (!res.ok) throw new Error('Failed')
      const body = await res.json()
      setTaxForms(body.data ?? [])
    } catch {
      setTaxForms([])
    } finally {
      setLoadingForms(false)
    }
  }

  useEffect(() => {
    loadRuns()
    loadArtists()
    loadForms()
  }, [studioId]) // eslint-disable-line react-hooks/exhaustive-deps

  const refresh = () => {
    loadRuns()
    loadArtists()
    loadForms()
  }

  const tabTriggerClass =
    'rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium data-[state=active]:bg-transparent data-[state=active]:shadow-none'

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-border shrink-0">
        <h1 className="text-2xl font-bold tracking-tight">Payroll</h1>
        {canManage && (
          <Button size="sm" onClick={() => setSheetOpen(true)}>
            <Plus className="h-4 w-4 mr-1.5" />
            New Run
          </Button>
        )}
      </div>

      {/* Tabs */}
      <Tabs defaultValue="runs" className="flex flex-col flex-1 mt-0">
        <TabsList className="w-full justify-start border-b border-border rounded-none bg-transparent h-auto px-6 gap-0 shrink-0">
          <TabsTrigger value="runs" className={tabTriggerClass}>Runs</TabsTrigger>
          <TabsTrigger value="artists-tax" className={tabTriggerClass}>Artists Tax Info</TabsTrigger>
          <TabsTrigger value="tax-forms-1099" className={tabTriggerClass}>1099-K Forms</TabsTrigger>
        </TabsList>

        <TabsContent value="runs" className="flex-1 mt-0">
          <PayrollRunsTab
            runs={runs}
            isLoading={loadingRuns}
            isOwner={isOwner}
            canManage={canManage}
          />
        </TabsContent>
        <TabsContent value="artists-tax" className="flex-1 mt-0">
          <ArtistsTaxInfoTab
            artists={artists}
            isLoading={loadingArtists}
          />
        </TabsContent>
        <TabsContent value="tax-forms-1099" className="flex-1 mt-0">
          <TaxForms1099Tab
            forms={taxForms}
            isLoading={loadingForms}
            canManage={canManage}
            canGenerate={canGenerate}
          />
        </TabsContent>
      </Tabs>

      {canManage && (
        <NewRunSheet
          open={sheetOpen}
          onOpenChange={setSheetOpen}
          onSuccess={() => {
            startTransition(() => {
              loadRuns()
            })
          }}
        />
      )}
    </div>
  )
}

import { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import type { PlanTier } from '@/lib/billing/feature-gate'

/**
 * GET /api/payroll/artists-tax-info
 *
 * Returns all artists in the studio with their masked tax info.
 * Used for the "Artists Tax Info" tab on the Payroll hub.
 */
export async function GET(_req: NextRequest) {
  const supabase = await createClient()

  const { data: { user }, error: authErr } = await supabase.auth.getUser()
  if (authErr || !user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No studio membership' }, { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const guard = requireFeature(plan, 'payroll')
  if (guard) return guard

  // Fetch all artists in the studio
  const { data: artists, error: artistsErr } = await supabase
    .from('artists')
    .select('id, full_name, avatar_url')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .order('full_name', { ascending: true })

  if (artistsErr) {
    logger.error({ err: artistsErr, studioId: member.studio_id }, 'artists list for tax info failed')
    return Response.json({ error: 'Failed to load artists' }, { status: 500 })
  }

  // Fetch masked tax info for all artists in one shot
  const { data: taxInfoRows } = await supabase
    .from('artist_tax_info')
    .select('artist_id, tin_last4, tin_type, legal_entity_type, legal_name, updated_at')
    .eq('studio_id', member.studio_id)

  const taxInfoMap = new Map(
    (taxInfoRows ?? []).map((t) => [t.artist_id, t])
  )

  const data = (artists ?? []).map((a) => ({
    artist_id: a.id,
    full_name: a.full_name,
    avatar_url: a.avatar_url,
    tax_info: taxInfoMap.get(a.id) ?? null,
  }))

  return Response.json({ data })
}

import type { Metadata } from 'next'
import { redirect, notFound } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { getUserPermissions } from '@/lib/team/permissions'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import { RunDetailView } from '@/components/payroll/RunDetailView'
import { logger } from '@/lib/logger'

export const metadata: Metadata = {
  title: 'Payroll Run — InkOS',
}

interface PageProps {
  params: Promise<{ id: string }>
}

export default async function PayrollRunPage({ params }: PageProps) {
  const { id } = await params
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) redirect('/onboarding')

  const studioId = member.studio_id
  const role = member.role as string

  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  if (!hasFeature(plan, 'payroll')) {
    return (
      <div className="flex flex-1 items-center justify-center p-8">
        <UpgradeGatePageBlock
          requiredPlan="pro"
          feature="Payroll & 1099-K"
          description="Upgrade to the Pro plan to access payroll runs."
        />
      </div>
    )
  }

  // Load run detail via RPC
  const { data: run, error } = await supabase.rpc('get_payroll_run_detail', { p_run_id: id })
  if (error) {
    logger.error({ err: error, runId: id }, 'get_payroll_run_detail on page load failed')
    throw new Error('Failed to load run')
  }
  if (!run) notFound()

  const permissionsSet = await getUserPermissions(studioId, user.id)
  const isOwner = role === 'owner'
  const canManage =
    isOwner ||
    permissionsSet.has('payroll.manage') ||
    permissionsSet.has('admin.all')

  return (
    <RunDetailView
      run={run}
      isOwner={isOwner}
      canManage={canManage}
    />
  )
}

