'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { ArrowLeft, CheckCircle2, XCircle, Loader2, MoreHorizontal } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from '@/components/ui/table'
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Separator } from '@/components/ui/separator'
import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { PayrollRunStatusBadge } from './PayrollRunStatusBadge'
import { ArtistPayStatusBadge } from './ArtistPayStatusBadge'
import { PayrollTimeline } from './PayrollTimeline'
import { PayrollStatsRow } from './PayrollStatsRow'
import { MarkPaidModal } from './MarkPaidModal'
import { formatCurrency } from '@/lib/utils'
import { formatPeriodRange, runLabel } from '@/lib/payroll/utils'
import type { PayrollRunDetail, PayrollArtistSummaryDetail } from '@/lib/supabase/types'

interface Props {
  run: PayrollRunDetail
  isOwner: boolean
  canManage: boolean
}

export function RunDetailView({ run: initial, isOwner, canManage }: Props) {
  const router = useRouter()
  const [data, setData] = useState<PayrollRunDetail>(initial)
  const [markPaidOpen, setMarkPaidOpen] = useState(false)
  const [confirmCancel, setConfirmCancel] = useState(false)
  const [confirmApprove, setConfirmApprove] = useState(false)
  const [confirmCalculate, setConfirmCalculate] = useState(false)
  const [isPending, startTransition] = useTransition()

  const { run, artist_summaries } = data

  const refresh = () => {
    startTransition(async () => {
      try {
        const res = await fetch(`/api/payroll/runs/${run.id}`)
        if (!res.ok) return
        const body = await res.json()
        if (body.data) setData(body.data)
      } catch {
        // silent — stale data acceptable; user can reload
      }
    })
  }

  const executeRunAction = (action: 'calculate' | 'approve' | 'cancel') => {
    startTransition(async () => {
      try {
        const res = await fetch(`/api/payroll/runs/${run.id}/${action}`, { method: 'POST' })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? `Failed to ${action}`)
        const messages: Record<string, string> = {
          calculate: 'Run calculated',
          approve: 'Run approved',
          cancel: 'Run cancelled',
        }
        toast.success(messages[action])
        router.refresh()
        refresh()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : `Failed to ${action} run`)
      }
    })
  }

  const displayLabel = runLabel(run.label, run.period_start)
  const periodRange = formatPeriodRange(run.period_start, run.period_end)
  const isCancelled = run.status === 'cancelled'
  const canCalculate = canManage && run.status === 'draft'
  const canApprove = isOwner && run.status === 'calculated'
  const canMarkPaid = isOwner && run.status === 'approved'
  const canCancel = isOwner && (run.status === 'draft' || run.status === 'calculated')

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-start justify-between px-6 py-4 border-b border-border shrink-0">
        <div className="flex items-start gap-3">
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 mt-0.5 shrink-0"
            onClick={() => router.push('/payroll')}
            aria-label="Back to Payroll"
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div className="space-y-0.5">
            <div className="flex items-center gap-2 flex-wrap">
              <h1 className="text-xl font-semibold tracking-tight">{displayLabel}</h1>
              <PayrollRunStatusBadge status={run.status} />
            </div>
            <p className="text-sm text-muted-foreground">{periodRange}</p>
            {run.notes && (
              <p className="text-xs text-muted-foreground mt-1 max-w-lg">{run.notes}</p>
            )}
          </div>
        </div>

        {/* Action buttons */}
        {!isCancelled && (
          <div className="flex items-center gap-2 shrink-0 ml-4">
            {canCalculate && (
              <Button
                size="sm"
                variant="outline"
                onClick={() => setConfirmCalculate(true)}
                disabled={isPending}
              >
                {isPending ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" /> : null}
                Calculate
              </Button>
            )}
            {canApprove && (
              <Button
                size="sm"
                variant="outline"
                onClick={() => setConfirmApprove(true)}
                disabled={isPending}
              >
                <CheckCircle2 className="h-4 w-4 mr-1.5" />
                Approve
              </Button>
            )}
            {canMarkPaid && (
              <Button
                size="sm"
                onClick={() => setMarkPaidOpen(true)}
                disabled={isPending}
              >
                Mark as Paid
              </Button>
            )}
            {canCancel && (
              <Button
                size="sm"
                variant="ghost"
                className="text-destructive hover:text-destructive"
                onClick={() => setConfirmCancel(true)}
                disabled={isPending}
              >
                <XCircle className="h-4 w-4 mr-1.5" />
                Cancel Run
              </Button>
            )}
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto">
        <div className="px-6 py-6 space-y-6">
          {/* Timeline */}
          <PayrollTimeline
            status={run.status}
            calculatedAt={run.calculated_at}
            approvedAt={run.approved_at}
            paidAt={run.paid_at}
          />

          {/* Stats */}
          <PayrollStatsRow
            grossCents={run.total_gross_cents}
            netCents={run.total_net_cents}
            deductionsCents={run.total_adjustments_cents}
          />

          {/* Run meta */}
          {(run.payment_method || run.paid_at) && (
            <div className="flex flex-wrap gap-x-6 gap-y-1 text-sm">
              {run.payment_method && (
                <span className="text-muted-foreground">
                  Paid via <span className="text-foreground font-medium capitalize">{run.payment_method.replace('_', ' ')}</span>
                </span>
              )}
              {run.payment_reference && (
                <span className="text-muted-foreground">
                  Ref: <span className="text-foreground font-mono text-xs">{run.payment_reference}</span>
                </span>
              )}
              {run.paid_at && (
                <span className="text-muted-foreground">
                  Paid on <span className="text-foreground font-medium">
                    {new Date(run.paid_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                  </span>
                </span>
              )}
            </div>
          )}

          <Separator />

          {/* Artist summaries */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-sm font-medium">
                Artist Payouts
                <span className="ml-2 text-muted-foreground font-normal">
                  {artist_summaries.length} artist{artist_summaries.length !== 1 ? 's' : ''}
                </span>
              </h2>
            </div>

            {artist_summaries.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 gap-2">
                <p className="text-sm font-medium text-muted-foreground">No artist summaries</p>
                <p className="text-xs text-muted-foreground">Calculate the run to generate per-artist breakdowns.</p>
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Artist</TableHead>
                    <TableHead className="tabular-nums">Gross</TableHead>
                    <TableHead className="tabular-nums">Net</TableHead>
                    <TableHead className="tabular-nums">Records</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Method</TableHead>
                    <TableHead className="w-10" />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {artist_summaries.map((summary) => (
                    <ArtistSummaryRow
                      key={summary.id}
                      summary={summary}
                      runStatus={run.status}
                      canManage={canManage}
                      onNavigate={(id) => router.push(`/payroll/artist-summaries/${id}`)}
                    />
                  ))}
                </TableBody>
              </Table>
            )}
          </div>
        </div>
      </div>

      {/* Modals */}
      {isOwner && (
        <MarkPaidModal
          open={markPaidOpen}
          onOpenChange={setMarkPaidOpen}
          runId={run.id}
          runLabel={displayLabel}
          onSuccess={() => {
            setMarkPaidOpen(false)
            router.refresh()
            refresh()
          }}
        />
      )}

      {/* Confirm calculate */}
      <AlertDialog open={confirmCalculate} onOpenChange={setConfirmCalculate}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Calculate payroll run?</AlertDialogTitle>
            <AlertDialogDescription>
              This will compute per-artist totals from approved commission records in this period.
              You can still cancel the run after calculating.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => { setConfirmCalculate(false); executeRunAction('calculate') }}>
              Calculate
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm approve */}
      <AlertDialog open={confirmApprove} onOpenChange={setConfirmApprove}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Approve payroll run?</AlertDialogTitle>
            <AlertDialogDescription>
              Once approved, commission records are locked and cannot be edited.
              Proceed only after reviewing all artist totals.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => { setConfirmApprove(false); executeRunAction('approve') }}>
              Approve Run
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm cancel */}
      <AlertDialog open={confirmCancel} onOpenChange={setConfirmCancel}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this payroll run?</AlertDialogTitle>
            <AlertDialogDescription>
              Cancelling releases all commission records back to draft. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive hover:bg-destructive/90"
              onClick={() => { setConfirmCancel(false); executeRunAction('cancel') }}
            >
              Cancel Run
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

