    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  if (!hasFeature(plan, 'payroll')) {
    return (
      <div className="flex flex-1 items-center justify-center p-8">
        <UpgradeGatePageBlock
          requiredPlan="pro"
          feature="Payroll & 1099-K"
          description="Upgrade to the Pro plan to access payroll runs."
        />
      </div>
    )
  }

  const { data: summary, error } = await supabase.rpc('get_payroll_artist_summary_detail', {
    p_summary_id: id,
  })
  if (error) {
    logger.error({ err: error, summaryId: id }, 'get_payroll_artist_summary_detail on page load failed')
    throw new Error('Failed to load artist summary')
  }
  if (!summary) notFound()

  const permissionsSet = await getUserPermissions(studioId, user.id)
  const isOwner = role === 'owner'
  const canManage =
    isOwner ||
    permissionsSet.has('payroll.manage') ||
    permissionsSet.has('admin.all')

  return (
    <ArtistSummaryDetailView
      summary={summary}
      isOwner={isOwner}
      canManage={canManage}
    />
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Separator } from '@/components/ui/separator'
import {
  Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { ArtistPayStatusBadge } from './ArtistPayStatusBadge'
import { PayrollStatsRow } from './PayrollStatsRow'
import { formatCurrency } from '@/lib/utils'
import { PAYMENT_METHODS } from '@/lib/payroll/constants'
import type { PayrollArtistSummaryDetail } from '@/lib/supabase/types'

interface Props {
  summary: PayrollArtistSummaryDetail
  isOwner: boolean
  canManage: boolean
}

export function ArtistSummaryDetailView({ summary: initial, isOwner, canManage }: Props) {
  const router = useRouter()
  const [summary, setSummary] = useState<PayrollArtistSummaryDetail>(initial)
  const [markPaidOpen, setMarkPaidOpen] = useState(false)
  const [paymentMethod, setPaymentMethod] = useState('')
  const [reference, setReference] = useState('')
  const [isPending, startTransition] = useTransition()

  const canMarkPaid =
    (isOwner || canManage) && summary.status === 'pending'

  const handleMarkPaid = () => {
    if (!paymentMethod) {
      toast.error('Select a payment method')
      return
    }
    startTransition(async () => {
      try {
        const res = await fetch(`/api/payroll/artist-summaries/${summary.id}/mark-paid`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            payment_method: paymentMethod,
            payment_reference: reference.trim() || null,
          }),
        })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? 'Failed to mark as paid')
        toast.success(`${summary.artist_name_snapshot} marked as paid`)
        setMarkPaidOpen(false)
        setPaymentMethod('')
        setReference('')
        // Refresh from API
        const detailRes = await fetch(`/api/payroll/artist-summaries/${summary.id}`)
        if (detailRes.ok) {
          const detailBody = await detailRes.json()
          if (detailBody.data) setSummary(detailBody.data)
        }
        router.refresh()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to mark as paid')
      }
    })
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-start justify-between px-6 py-4 border-b border-border shrink-0">
        <div className="flex items-start gap-3">
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 mt-0.5 shrink-0"
            onClick={() => router.back()}
            aria-label="Go back"
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div className="space-y-0.5">
            <div className="flex items-center gap-2 flex-wrap">
              <h1 className="text-xl font-semibold tracking-tight">
                {summary.artist_name_snapshot}
              </h1>
              <ArtistPayStatusBadge status={summary.status} />
            </div>
            <p className="text-sm text-muted-foreground">Artist payout detail</p>
          </div>
        </div>
        {canMarkPaid && (
          <Button
            size="sm"
            onClick={() => setMarkPaidOpen(true)}
            disabled={isPending}
          >
            Mark as Paid
          </Button>
        )}
      </div>

      <div className="flex-1 overflow-y-auto">
        <div className="px-6 py-6 space-y-6">
          {/* Stats */}
          <PayrollStatsRow
            grossCents={summary.gross_total_cents}
            netCents={summary.net_total_cents}
            deductionsCents={summary.deductions_cents}
          />

          <Separator />

          {/* Breakdown table */}
          <div className="space-y-3">
            <h2 className="text-sm font-medium">Payout Breakdown</h2>
            <div className="rounded-md border border-border overflow-hidden">
              <table className="w-full text-sm">
                <tbody className="divide-y divide-border">
                  <tr>
                    <td className="px-4 py-2.5 text-muted-foreground">Commissions ({summary.commission_count})</td>
                    <td className="px-4 py-2.5 text-right tabular-nums font-medium">
                      {formatCurrency(summary.commission_total_cents)}
                    </td>
                  </tr>
                  <tr>
                    <td className="px-4 py-2.5 text-muted-foreground">Tips</td>
                    <td className="px-4 py-2.5 text-right tabular-nums font-medium">
                      {formatCurrency(summary.tip_total_cents)}
                    </td>
                  </tr>
                  {summary.adjustment_count > 0 && (
                    <tr>
                      <td className="px-4 py-2.5 text-muted-foreground">
                        Adjustments ({summary.adjustment_count})
                      </td>
                      <td className="px-4 py-2.5 text-right tabular-nums font-medium">
                        {formatCurrency(summary.adjustment_total_cents)}
                      </td>
                    </tr>
                  )}
                  {summary.deductions_cents > 0 && (
                    <tr>
                      <td className="px-4 py-2.5 text-muted-foreground">Deductions</td>
                      <td className="px-4 py-2.5 text-right tabular-nums font-medium text-destructive">
                        −{formatCurrency(summary.deductions_cents)}
                      </td>
                    </tr>
                  )}
                  <tr className="bg-muted/30">
                    <td className="px-4 py-2.5 font-medium">Net payout</td>
                    <td className="px-4 py-2.5 text-right tabular-nums font-semibold">
                      {formatCurrency(summary.net_total_cents)}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>

          {/* Payment details (if paid) */}
          {summary.status === 'paid' && (
            <>
              <Separator />
              <div className="space-y-2">
                <h2 className="text-sm font-medium">Payment Details</h2>
                <div className="flex flex-wrap gap-x-6 gap-y-1 text-sm">
                  {summary.payment_method && (
                    <span className="text-muted-foreground">
                      Method:{' '}
                      <span className="text-foreground font-medium capitalize">
                        {summary.payment_method.replace('_', ' ')}
                      </span>
                    </span>
                  )}
                  {summary.payment_reference && (
                    <span className="text-muted-foreground">
                      Ref:{' '}
                      <span className="text-foreground font-mono text-xs">
                        {summary.payment_reference}
                      </span>
                    </span>
                  )}
                  {summary.paid_at && (
                    <span className="text-muted-foreground">
                      Paid on:{' '}
                      <span className="text-foreground font-medium">
                        {new Date(summary.paid_at).toLocaleDateString('en-US', {
                          month: 'short',
                          day: 'numeric',
                          year: 'numeric',
                        })}
                      </span>
                    </span>
                  )}
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Mark paid dialog */}
      <Dialog open={markPaidOpen} onOpenChange={(open) => {
        if (!open) { setPaymentMethod(''); setReference('') }
        setMarkPaidOpen(open)
      }}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Mark Artist as Paid</DialogTitle>
            <DialogDescription>
              Recording payment for {summary.artist_name_snapshot} —{' '}
              {formatCurrency(summary.net_total_cents)} net
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-1.5">
              <Label>Payment method</Label>
              <Select value={paymentMethod} onValueChange={setPaymentMethod}>
                <SelectTrigger>
                  <SelectValue placeholder="Select method…" />
                </SelectTrigger>
                <SelectContent>
                  {PAYMENT_METHODS.map((m) => (
                    <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="artist-ref">
                Reference <span className="text-muted-foreground">(optional)</span>
              </Label>
              <Input
                id="artist-ref"
                placeholder="Check #, transaction ID, etc."
                value={reference}
                onChange={(e) => setReference(e.target.value)}
                maxLength={200}
              />
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setMarkPaidOpen(false)}
              disabled={isPending}
            >
              Cancel
            </Button>
            <Button
              onClick={handleMarkPaid}
              disabled={isPending || !paymentMethod}
            >
              {isPending && <Loader2 className="h-4 w-4 animate-spin mr-1.5" />}
              Mark as Paid
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect, notFound } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { getUserPermissions } from '@/lib/team/permissions'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import { TaxForm1099ReviewView } from '@/components/payroll/TaxForm1099ReviewView'
import { logger } from '@/lib/logger'

export const metadata: Metadata = {
  title: '1099-K Form — InkOS',
}

interface PageProps {
  params: Promise<{ id: string }>
}

export default async function TaxForm1099Page({ params }: PageProps) {
  const { id } = await params
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) redirect('/onboarding')

  const studioId = member.studio_id
  const role = member.role as string

  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  if (!hasFeature(plan, 'payroll')) {
    return (
      <div className="flex flex-1 items-center justify-center p-8">
        <UpgradeGatePageBlock
          requiredPlan="pro"
          feature="Payroll & 1099-K"
          description="Upgrade to the Pro plan to access tax forms."
        />
      </div>
    )
  }

  const { data: form, error } = await supabase.rpc('get_tax_form_detail', { p_form_id: id })
  if (error) {
    logger.error({ err: error, formId: id }, 'get_tax_form_detail on page load failed')
    throw new Error('Failed to load tax form')
  }
  if (!form) notFound()

  // Fetch artist info for this form
  const { data: artist } = await supabase
    .from('artists')
    .select('id, full_name, email, avatar_url')
    .eq('id', (form as { artist_id: string }).artist_id)
    .single()

  const permissionsSet = await getUserPermissions(studioId, user.id)
  const isOwner = role === 'owner'
  const canManage =
    isOwner ||
    permissionsSet.has('payroll.manage') ||
    permissionsSet.has('admin.all')
  const canGenerate =
    isOwner ||
    permissionsSet.has('tax_forms.generate') ||
    permissionsSet.has('admin.all')

  return (
    <TaxForm1099ReviewView
      form={form}
      artist={artist ?? null}
      isOwner={isOwner}
      canManage={canManage}
      canGenerate={canGenerate}
    />
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Download, Send, FileText, Lock, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Separator } from '@/components/ui/separator'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { TaxFormStatusBadge } from './TaxFormStatusBadge'
import { ThresholdBadge } from './ThresholdBadge'
import { LockedFormBadge } from './LockedFormBadge'
import { formatCurrency } from '@/lib/utils'
import type { TaxForm } from '@/lib/supabase/types'

interface ArtistInfo {
  id: string
  full_name: string | null
  email: string | null
  avatar_url: string | null
}

interface Props {
  form: TaxForm
  artist: ArtistInfo | null
  isOwner: boolean
  canManage: boolean
  canGenerate: boolean
}

export function TaxForm1099ReviewView({ form: initial, artist, isOwner, canManage, canGenerate }: Props) {
  const router = useRouter()
  const [form, setForm] = useState<TaxForm>(initial)
  const [confirmSend, setConfirmSend] = useState(false)
  const [confirmLock, setConfirmLock] = useState(false)
  const [confirmVoid, setConfirmVoid] = useState(false)
  const [isPending, startTransition] = useTransition()
  const [isGeneratingPdf, startGeneratingPdf] = useTransition()

  const refreshForm = async () => {
    try {
      const res = await fetch(`/api/tax-forms/${form.id}`)
      if (res.ok) {
        const body = await res.json()
        if (body.data) setForm(body.data)
      }
    } catch {
      // silent
    }
  }

  const handleGeneratePdf = () => {
    startGeneratingPdf(async () => {
      try {
        const res = await fetch(`/api/tax-forms/${form.id}/generate-pdf`, { method: 'POST' })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? 'PDF generation failed')
        toast.success('PDF generation queued — check back shortly')
        await refreshForm()
        router.refresh()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to generate PDF')
      }
    })
  }

  const handleSend = () => {
    startTransition(async () => {
      try {
        const res = await fetch(`/api/tax-forms/${form.id}/send`, { method: 'POST' })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? 'Send failed')
        toast.success('1099-K queued for delivery')
        setConfirmSend(false)
        await refreshForm()
        router.refresh()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to send form')
        setConfirmSend(false)
      }
    })
  }

  const handleVoid = () => {
    startTransition(async () => {
      try {
        const res = await fetch(`/api/tax-forms/${form.id}/void`, { method: 'POST' })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? 'Void failed')
        toast.success('Form voided')
        setConfirmVoid(false)
        await refreshForm()
        router.refresh()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to void form')
        setConfirmVoid(false)
      }
    })
  }

  const handleLock = () => {
    startTransition(async () => {
      try {
        const res = await fetch(`/api/tax-forms/${form.id}/lock`, { method: 'POST' })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? 'Lock failed')
        toast.success('Form locked')
        setConfirmLock(false)
        await refreshForm()
        router.refresh()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to lock form')
        setConfirmLock(false)
      }
    })
  }

  const isLocked = !!form.locked_at
  const isVoided = form.status === 'voided'
  const hasPdf = !!form.pdf_storage_path
  const canSend = canManage && hasPdf && !isVoided
  const canVoid = canManage && !isLocked && !isVoided
  const canLock = isOwner && !isLocked && form.status === 'sent'

  const artistName = artist?.full_name ?? 'Unknown Artist'
  const artistInitials = artistName
    .split(' ')
    .slice(0, 2)
    .map((n) => n[0])
    .join('')
    .toUpperCase()

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-start justify-between px-6 py-4 border-b border-border shrink-0">
        <div className="flex items-start gap-3">
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 mt-0.5 shrink-0"
            onClick={() => router.push('/payroll')}
            aria-label="Back to Payroll"
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div className="space-y-0.5">
            <div className="flex items-center gap-2 flex-wrap">
              <h1 className="text-xl font-semibold tracking-tight">
                1099-K — {artistName} — {form.tax_year}
              </h1>
              <TaxFormStatusBadge status={form.status} />
              {isLocked && <LockedFormBadge />}
            </div>
            <p className="text-sm text-muted-foreground">
              Tax year {form.tax_year}
              {form.correction_of && (
                <span className="ml-2 text-xs text-muted-foreground">Correction</span>
              )}
            </p>
          </div>
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2 shrink-0 ml-4 flex-wrap justify-end">
          {hasPdf && (
            <Button variant="outline" size="sm" asChild>
              <a href={`/api/tax-forms/${form.id}/download`} download>
                <Download className="h-4 w-4 mr-1.5" />
                Download PDF
              </a>
            </Button>
          )}
          {canGenerate && !hasPdf && !isVoided && (
            <Button
              variant="outline"
              size="sm"
              onClick={handleGeneratePdf}
              disabled={isGeneratingPdf}
            >
              {isGeneratingPdf
                ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
                : <FileText className="h-4 w-4 mr-1.5" />
              }
              Generate PDF
            </Button>
          )}
          {canSend && (
            <Button size="sm" onClick={() => setConfirmSend(true)} disabled={isPending}>
              <Send className="h-4 w-4 mr-1.5" />
              Send to Artist
            </Button>
          )}
          {canLock && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => setConfirmLock(true)}
              disabled={isPending}
            >
              <Lock className="h-4 w-4 mr-1.5" />
              Lock Form
            </Button>
          )}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto">
        <div className="px-6 py-6 space-y-6 max-w-2xl">
          {/* Artist card */}
          <div className="flex items-center gap-3 p-4 rounded-lg border border-border bg-card">
            <Avatar className="h-10 w-10">
              <AvatarImage src={artist?.avatar_url ?? undefined} />
              <AvatarFallback>{artistInitials}</AvatarFallback>
            </Avatar>
            <div>
              <p className="text-sm font-medium">{artistName}</p>
              {artist?.email && (
                <p className="text-xs text-muted-foreground">{artist.email}</p>
              )}
            </div>
          </div>

          {/* Form data */}
          <div className="space-y-3">
            <h2 className="text-sm font-medium">Form Summary</h2>
            <div className="rounded-md border border-border overflow-hidden">
              <table className="w-full text-sm">
                <tbody className="divide-y divide-border">
                  <tr>
                    <td className="px-4 py-2.5 text-muted-foreground w-1/2">Form type</td>
                    <td className="px-4 py-2.5 font-medium">{form.form_type}</td>
                  </tr>
                  <tr>
                    <td className="px-4 py-2.5 text-muted-foreground">Tax year</td>
                    <td className="px-4 py-2.5 font-medium">{form.tax_year}</td>
                  </tr>
                  <tr>
                    <td className="px-4 py-2.5 text-muted-foreground">Gross amount</td>
                    <td className="px-4 py-2.5 tabular-nums font-semibold">
                      {formatCurrency(form.gross_amount_cents)}
                    </td>
                  </tr>
                  <tr>
                    <td className="px-4 py-2.5 text-muted-foreground">Transaction count</td>
                    <td className="px-4 py-2.5 tabular-nums">{form.transaction_count}</td>
                  </tr>
                  <tr>
                    <td className="px-4 py-2.5 text-muted-foreground">IRS threshold</td>
                    <td className="px-4 py-2.5">
                      <ThresholdBadge grossCents={form.gross_amount_cents} />
                    </td>
                  </tr>
                  <tr>
                    <td className="px-4 py-2.5 text-muted-foreground">Status</td>
                    <td className="px-4 py-2.5">
                      <TaxFormStatusBadge status={form.status} />
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>

          {/* Delivery info */}
          {(form.sent_at || form.sent_to_email) && (
            <>
              <Separator />
              <div className="space-y-2">
                <h2 className="text-sm font-medium">Delivery</h2>
                <div className="flex flex-wrap gap-x-6 gap-y-1 text-sm">
                  {form.sent_at && (
                    <span className="text-muted-foreground">
                      Sent on{' '}
                      <span className="text-foreground font-medium">
                        {new Date(form.sent_at).toLocaleDateString('en-US', {
                          month: 'short',
                          day: 'numeric',
                          year: 'numeric',
                        })}
                      </span>
                    </span>
                  )}
                  {form.sent_to_email && (
                    <span className="text-muted-foreground">
                      To <span className="text-foreground font-mono text-xs">{form.sent_to_email}</span>
                    </span>
                  )}
                </div>
              </div>
            </>
          )}

          {/* Lock info */}
          {isLocked && form.locked_at && (
            <>
              <Separator />
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <Lock className="h-3.5 w-3.5 shrink-0" />
                Locked on{' '}
                {new Date(form.locked_at).toLocaleDateString('en-US', {
                  month: 'short',
                  day: 'numeric',
                  year: 'numeric',
                })}
              </div>
            </>
          )}

          {/* Notes */}
          {form.notes && (
            <>
              <Separator />
              <div className="space-y-1">
                <h2 className="text-sm font-medium">Notes</h2>
                <p className="text-sm text-muted-foreground">{form.notes}</p>
              </div>
            </>
          )}

          {/* Void action */}
          {canVoid && (
            <>
              <Separator />
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-destructive">Void form</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Permanently marks this form as voided. Issue a correction if already sent.
                  </p>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  className="text-destructive border-destructive/30 hover:bg-destructive/10"
                  onClick={() => setConfirmVoid(true)}
                  disabled={isPending}
                >
                  Void Form
                </Button>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Confirm send */}
      <AlertDialog open={confirmSend} onOpenChange={setConfirmSend}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Send 1099-K to {artistName}?</AlertDialogTitle>
            <AlertDialogDescription>
              The PDF will be emailed to the artist. This action is permanent.
              Ensure the tax information and gross amount are accurate before sending.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleSend} disabled={isPending}>
              {isPending && <Loader2 className="h-4 w-4 animate-spin mr-1.5" />}
              Send
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm lock */}
      <AlertDialog open={confirmLock} onOpenChange={setConfirmLock}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Lock this form?</AlertDialogTitle>
            <AlertDialogDescription>
              Locking prevents any further changes to this 1099-K form, including corrections.
              This is typically done after filing with the IRS.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleLock} disabled={isPending}>
              Lock Form
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm void */}
      <AlertDialog open={confirmVoid} onOpenChange={setConfirmVoid}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Void this 1099-K form?</AlertDialogTitle>
            <AlertDialogDescription>
              Voiding is permanent. If this form has been sent to the artist, issue a correction instead.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive hover:bg-destructive/90"
              onClick={handleVoid}
              disabled={isPending}
            >
              {isPending && <Loader2 className="h-4 w-4 animate-spin mr-1.5" />}
              Void Form
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect, notFound } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { getUserPermissions } from '@/lib/team/permissions'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import { W9Form } from '@/components/artists/W9Form'
import { logger } from '@/lib/logger'

export const metadata: Metadata = {
  title: 'Tax Info (W-9) — InkOS',
}

interface PageProps {
  params: Promise<{ id: string }>
}

export default async function ArtistTaxInfoPage({ params }: PageProps) {
  const { id: artistId } = await params
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) redirect('/onboarding')

  const studioId = member.studio_id
  const role = member.role as string

  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  if (!hasFeature(plan, 'payroll')) {
    return (
      <div className="flex flex-1 items-center justify-center p-8">
        <UpgradeGatePageBlock
          requiredPlan="pro"
          feature="Payroll & 1099-K"
          description="Upgrade to the Pro plan to collect W-9 tax information."
        />
      </div>
    )
  }

  // Fetch artist
  const { data: artist } = await supabase
    .from('artists')
    .select('id, full_name, avatar_url, status, studio_id')
    .eq('id', artistId)
    .eq('studio_id', studioId)
    .single()
  if (!artist) notFound()

  // Fetch current masked tax info (null if not collected)
  const { data: taxInfo, error: taxErr } = await supabase.rpc('get_artist_tax_info_masked', {
    p_artist_id: artistId,
  })
  if (taxErr) {
    logger.error({ err: taxErr, artistId }, 'get_artist_tax_info_masked on page load failed')
    throw new Error('Failed to load tax information')
  }

  const permissionsSet = await getUserPermissions(studioId, user.id)
  const isOwner = role === 'owner'
  const canManage =
    isOwner ||
    permissionsSet.has('payroll.manage') ||
    permissionsSet.has('admin.all')

  return (
    <W9Form
      artistId={artistId}
      artistName={artist.full_name ?? 'Artist'}
      existingTaxInfo={taxInfo ?? null}
      canManage={canManage}
    />
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { ArrowLeft, ShieldCheck, Loader2, CheckCircle2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/components/ui/select'
import { Separator } from '@/components/ui/separator'
import { Checkbox } from '@/components/ui/checkbox'
import { SecurityCallout } from '@/components/payroll/SecurityCallout'
import { W9StatusBadge } from '@/components/payroll/W9StatusBadge'
import { formatAddress } from '@/lib/payroll/utils'
import type { ArtistTaxInfoMasked } from '@/lib/supabase/types'

const W9Schema = z.object({
  legal_name: z.string().min(1, 'Legal name is required').max(200),
  legal_entity_type: z.enum([
    'individual', 'sole_proprietor', 'llc_single', 'llc_multi',
    'corporation', 's_corp', 'partnership', 'trust_estate',
    'exempt_payee', 'other',
  ], { required_error: 'Entity type is required' }),
  tin_type: z.enum(['ssn', 'ein'], { required_error: 'TIN type is required' }),
  tin_plaintext: z.string()
    .min(9, 'TIN must be at least 9 digits')
    .max(11, 'TIN is too long')
    .regex(/^[\d-\s]+$/, 'TIN can only contain digits, dashes, or spaces'),
  address_street: z.string().min(1, 'Street is required').max(200),
  address_city: z.string().min(1, 'City is required').max(100),
  address_state: z.string().length(2, 'Use 2-letter state code'),
  address_zip: z.string().min(5, 'ZIP is required').max(10),
  backup_withholding: z.boolean().default(false),
  certify: z.boolean().refine((v) => v === true, {
    message: 'You must certify the information is correct',
  }),
  w9_signature: z.string().min(1, 'Signature is required').max(200),
})

type W9FormValues = z.infer<typeof W9Schema>

const ENTITY_TYPES: { value: W9FormValues['legal_entity_type']; label: string }[] = [
  { value: 'individual',     label: 'Individual / Person' },
  { value: 'sole_proprietor', label: 'Sole Proprietor' },
  { value: 'llc_single',    label: 'LLC (Single-member)' },
  { value: 'llc_multi',     label: 'LLC (Multi-member)' },
  { value: 'corporation',   label: 'Corporation' },
  { value: 's_corp',        label: 'S Corporation' },
  { value: 'partnership',   label: 'Partnership' },
  { value: 'trust_estate',  label: 'Trust / Estate' },
  { value: 'exempt_payee',  label: 'Exempt Payee' },
  { value: 'other',         label: 'Other' },
]

interface Props {
  artistId: string
  artistName: string
  existingTaxInfo: ArtistTaxInfoMasked | null
  canManage: boolean
}

export function W9Form({ artistId, artistName, existingTaxInfo, canManage }: Props) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [submitted, setSubmitted] = useState(false)

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    formState: { errors },
  } = useForm<W9FormValues>({
    resolver: zodResolver(W9Schema),
    defaultValues: {
      legal_name: existingTaxInfo?.legal_name ?? '',
      legal_entity_type: (existingTaxInfo?.legal_entity_type as W9FormValues['legal_entity_type']) ?? undefined,
      tin_type: (existingTaxInfo?.tin_type as W9FormValues['tin_type']) ?? undefined,
      tin_plaintext: '',
      address_street: '',
      address_city: '',
      address_state: '',
      address_zip: '',
      backup_withholding: existingTaxInfo?.backup_withholding ?? false,
      certify: false,
      w9_signature: '',
    },
  })

  const certifyValue = watch('certify')
  const backupValue = watch('backup_withholding')

  const onSubmit = handleSubmit((values) => {
    startTransition(async () => {
      try {
        const res = await fetch(`/api/tax-info/artists/${artistId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            legal_name: values.legal_name,
            legal_entity_type: values.legal_entity_type,
            tin_type: values.tin_type,
            tin_plaintext: values.tin_plaintext,
            address: {
              street: values.address_street,
              city: values.address_city,
              state: values.address_state,
              zip: values.address_zip,
              country: 'US',
            },
            backup_withholding: values.backup_withholding,
            certify: values.certify,
            w9_signature: values.w9_signature,
          }),
        })
        const body = await res.json()
        if (!res.ok) throw new Error(body.error ?? 'Failed to save tax info')
        toast.success('W-9 information saved')
        setSubmitted(true)
        router.refresh()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to save tax info')
      }
    })
  })

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-start gap-3 px-6 py-4 border-b border-border shrink-0">
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8 mt-0.5 shrink-0"
          onClick={() => router.back()}
          aria-label="Go back"
        >
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <div className="space-y-0.5">
          <div className="flex items-center gap-2 flex-wrap">
            <h1 className="text-xl font-semibold tracking-tight">
              W-9 Tax Information — {artistName}
            </h1>
            {existingTaxInfo && (
              <W9StatusBadge signedAt={existingTaxInfo.w9_signed_at} />
            )}
          </div>
          <p className="text-sm text-muted-foreground">
            Required for 1099-K filing. Information is encrypted at rest.
          </p>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto">
        <div className="px-6 py-6 max-w-xl space-y-6">
          {/* Existing info summary */}
          {existingTaxInfo && !submitted && (
            <div className="rounded-lg border border-border bg-muted/30 p-4 space-y-2">
              <p className="text-sm font-medium">Current information on file</p>
              <div className="text-sm text-muted-foreground space-y-1">
                {existingTaxInfo.legal_name && (
                  <p>Legal name: <span className="text-foreground">{existingTaxInfo.legal_name}</span></p>
                )}
                {existingTaxInfo.tin_type && existingTaxInfo.tin_last4 && (
                  <p>
                    {existingTaxInfo.tin_type.toUpperCase()}:{' '}
                    <span className="font-mono text-foreground">
                      {existingTaxInfo.tin_type === 'ssn' ? `***-**-${existingTaxInfo.tin_last4}` : `**-***${existingTaxInfo.tin_last4}`}
                    </span>
                  </p>
                )}
                {existingTaxInfo.address && (
                  <p>Address: <span className="text-foreground">{formatAddress(existingTaxInfo.address as Record<string, string>)}</span></p>
                )}
              </div>
              {canManage && (
                <p className="text-xs text-muted-foreground pt-1">
                  Submit the form below to update this information.
                </p>
              )}
            </div>
          )}

          {submitted && (
            <div className="rounded-lg border border-green-200 bg-green-50 dark:bg-green-900/10 dark:border-green-900/30 p-4 flex items-center gap-3">
              <CheckCircle2 className="h-5 w-5 text-green-600 shrink-0" />
              <p className="text-sm text-green-800 dark:text-green-400">
                W-9 information saved successfully.
              </p>
            </div>
          )}

          {canManage && (
            <>
              <SecurityCallout message="TIN is encrypted in transit and at rest. Only the last 4 digits are shown after saving. Staff cannot view the full TIN." />

              <form onSubmit={onSubmit} className="space-y-5">
                {/* Legal name */}
                <div className="space-y-1.5">
                  <Label htmlFor="legal_name">Legal name on tax return</Label>
                  <Input
                    id="legal_name"
                    {...register('legal_name')}
                    placeholder="Full legal name"
                    aria-invalid={!!errors.legal_name}
                  />
                  {errors.legal_name && (
                    <p className="text-xs text-destructive" role="alert">{errors.legal_name.message}</p>
                  )}
                </div>

                {/* Entity type */}
                <div className="space-y-1.5">
                  <Label>Federal tax classification</Label>
                  <Select onValueChange={(v) => setValue('legal_entity_type', v as W9FormValues['legal_entity_type'])}>
                    <SelectTrigger aria-invalid={!!errors.legal_entity_type}>
                      <SelectValue placeholder="Select classification…" />
                    </SelectTrigger>
                    <SelectContent>
                      {ENTITY_TYPES.map((t) => (
                        <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {errors.legal_entity_type && (
                    <p className="text-xs text-destructive" role="alert">{errors.legal_entity_type.message}</p>
                  )}
                </div>

                <Separator />

                {/* TIN */}
                <div className="space-y-3">
                  <p className="text-sm font-medium">Taxpayer identification number</p>
                  <div className="space-y-1.5">
                    <Label>TIN type</Label>
                    <Select onValueChange={(v) => setValue('tin_type', v as W9FormValues['tin_type'])}>
                      <SelectTrigger aria-invalid={!!errors.tin_type}>
                        <SelectValue placeholder="SSN or EIN?" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="ssn">SSN (Social Security Number)</SelectItem>
                        <SelectItem value="ein">EIN (Employer Identification Number)</SelectItem>
                      </SelectContent>
                    </Select>
                    {errors.tin_type && (
                      <p className="text-xs text-destructive" role="alert">{errors.tin_type.message}</p>
                    )}
                  </div>
                  <div className="space-y-1.5">
                    <Label htmlFor="tin_plaintext">
                      TIN{' '}
                      <span className="text-muted-foreground font-normal">(encrypted — not stored in plaintext)</span>
                    </Label>
                    <Input
                      id="tin_plaintext"
                      {...register('tin_plaintext')}
                      placeholder="000-00-0000"
                      autoComplete="off"
                      data-lpignore="true"
                      aria-invalid={!!errors.tin_plaintext}
                    />
                    {errors.tin_plaintext && (
                      <p className="text-xs text-destructive" role="alert">{errors.tin_plaintext.message}</p>
                    )}
                    {existingTaxInfo?.tin_last4 && (
                      <p className="text-xs text-muted-foreground">
                        Current: ending in <span className="font-mono">{existingTaxInfo.tin_last4}</span>. Enter new TIN to update.
                      </p>
                    )}
                  </div>
                </div>

                <Separator />

                {/* Address */}
                <div className="space-y-3">
                  <p className="text-sm font-medium">Address</p>
                  <div className="space-y-1.5">
                    <Label htmlFor="address_street">Street address</Label>
                    <Input
                      id="address_street"
                      {...register('address_street')}
                      placeholder="123 Main St"
                      aria-invalid={!!errors.address_street}
                    />
                    {errors.address_street && (
                      <p className="text-xs text-destructive" role="alert">{errors.address_street.message}</p>
                    )}
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1.5">
                      <Label htmlFor="address_city">City</Label>
                      <Input
                        id="address_city"
                        {...register('address_city')}
                        placeholder="City"
                        aria-invalid={!!errors.address_city}
                      />
                      {errors.address_city && (
                        <p className="text-xs text-destructive" role="alert">{errors.address_city.message}</p>
                      )}
                    </div>
                    <div className="space-y-1.5">
                      <Label htmlFor="address_state">State</Label>
                      <Input
                        id="address_state"
                        {...register('address_state')}
                        placeholder="CA"
                        maxLength={2}
                        aria-invalid={!!errors.address_state}
                      />
                      {errors.address_state && (
                        <p className="text-xs text-destructive" role="alert">{errors.address_state.message}</p>
                      )}
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <Label htmlFor="address_zip">ZIP code</Label>
                    <Input
                      id="address_zip"
                      {...register('address_zip')}
                      placeholder="90210"
                      maxLength={10}
                      aria-invalid={!!errors.address_zip}
                    />
                    {errors.address_zip && (
                      <p className="text-xs text-destructive" role="alert">{errors.address_zip.message}</p>
                    )}
                  </div>
                </div>

                <Separator />

                {/* Backup withholding */}
                <div className="flex items-start gap-2">
                  <Checkbox
                    id="backup_withholding"
                    checked={backupValue}
                    onCheckedChange={(checked) => setValue('backup_withholding', !!checked)}
                  />
                  <Label htmlFor="backup_withholding" className="font-normal leading-snug cursor-pointer">
                    Subject to backup withholding
                    <span className="block text-xs text-muted-foreground mt-0.5">
                      Check if notified by IRS of under-reporting interest or dividends.
                    </span>
                  </Label>
                </div>

                <Separator />

                {/* Signature */}
                <div className="space-y-3">
                  <div className="space-y-1.5">
                    <Label htmlFor="w9_signature">
                      Signature (type full legal name)
                    </Label>
                    <Input
                      id="w9_signature"
                      {...register('w9_signature')}
                      placeholder="Full name as signature"
                      aria-invalid={!!errors.w9_signature}
                    />
                    {errors.w9_signature && (
                      <p className="text-xs text-destructive" role="alert">{errors.w9_signature.message}</p>
                    )}
                  </div>
                  <div className="flex items-start gap-2">
                    <Checkbox
                      id="certify"
                      checked={certifyValue}
                      onCheckedChange={(checked) => setValue('certify', !!checked)}
                      aria-invalid={!!errors.certify}
                    />
                    <Label htmlFor="certify" className="font-normal leading-snug cursor-pointer text-sm">
                      Under penalties of perjury, I certify that the TIN above is correct and I am not
                      subject to backup withholding (unless checked above), and I am a U.S. person.
                    </Label>
                  </div>
                  {errors.certify && (
                    <p className="text-xs text-destructive" role="alert">{errors.certify.message}</p>
                  )}
                </div>

                <div className="flex justify-end pt-2">
                  <Button
                    type="submit"
                    disabled={isPending || !certifyValue}
                    className="min-w-[120px]"
                  >
                    {isPending && <Loader2 className="h-4 w-4 animate-spin mr-1.5" />}
                    {isPending ? 'Saving…' : 'Save W-9'}
                  </Button>
                </div>
              </form>
            </>
          )}

          {!canManage && (
            <div className="flex flex-col items-center justify-center py-16 gap-2">
              <ShieldCheck className="h-10 w-10 text-muted-foreground/40" />
              <p className="text-sm font-medium">Owner or admin access required</p>
              <p className="text-xs text-muted-foreground">Contact your studio owner to update tax information.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { Receipt } from 'lucide-react'
import { formatCurrency } from '@/lib/utils'
import { formatPeriodRange } from '@/lib/payroll/utils'
import { ArtistPayStatusBadge } from '@/components/payroll/ArtistPayStatusBadge'
import type { PayrollArtistSummary } from '@/lib/supabase/types'

interface Props {
  artistId: string
}

// The `/api/payroll/artist-summaries?artist_id=` endpoint returns PayrollArtistSummary[]
// augmented with period_start / period_end from the parent run.
interface SummaryWithPeriod extends PayrollArtistSummary {
  period_start: string
  period_end: string
}

export function PayrollHistorySection({ artistId }: Props) {
  const router = useRouter()
  const [summaries, setSummaries] = useState<SummaryWithPeriod[] | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    let cancelled = false
    setIsLoading(true)
    fetch(`/api/payroll/artist-summaries?artist_id=${artistId}`)
      .then((r) => r.json())
      .then((body) => {
        if (!cancelled) setSummaries(body.data ?? [])
      })
      .catch(() => {
        if (!cancelled) setSummaries([])
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false)
      })
    return () => { cancelled = true }
  }, [artistId])

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 3 }).map((_, i) => (
          <div key={i} className="flex items-center gap-3">
            <Skeleton className="h-4 w-32" />
            <Skeleton className="h-4 w-20" />
            <Skeleton className="h-5 w-16 rounded-full" />
          </div>
        ))}
      </div>
    )
  }

  if (!summaries || summaries.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-10 gap-2">
        <Receipt className="h-8 w-8 text-muted-foreground/40" />
        <p className="text-sm text-muted-foreground">No payroll history yet</p>
      </div>
    )
  }

  return (
    <div className="space-y-1">
      {summaries.map((s) => (
        <div
          key={s.id}
          className="flex items-center gap-4 py-2 px-3 rounded-md hover:bg-muted/50 cursor-pointer transition-colors"
          onClick={() => router.push(`/payroll/artist-summaries/${s.id}`)}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => { if (e.key === 'Enter') router.push(`/payroll/artist-summaries/${s.id}`) }}
        >
          <span className="text-sm text-muted-foreground flex-1 truncate">
            {formatPeriodRange(s.period_start, s.period_end)}
          </span>
          <span className="tabular-nums text-sm font-medium">
            {formatCurrency(s.net_total_cents)}
          </span>
          <ArtistPayStatusBadge status={s.status} />
          <Button
            variant="ghost"
            size="sm"
            className="h-7 px-2 text-xs text-muted-foreground"
            onClick={(e) => {
              e.stopPropagation()
              router.push(`/payroll/artist-summaries/${s.id}`)
            }}
          >
            View
          </Button>
        </div>
      ))}
    </div>
  )
}

import { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import type { PlanTier } from '@/lib/billing/feature-gate'

/**
 * GET /api/payroll/artist-summaries?artist_id=<uuid>
 *
 * Returns payroll summaries for a specific artist, joined with period dates from
 * the parent payroll run. Used by PayrollHistorySection on the artist detail page.
 */
export async function GET(req: NextRequest) {
  const { searchParams } = req.nextUrl
  const artistId = searchParams.get('artist_id')
  if (!artistId) return Response.json({ error: 'artist_id is required' }, { status: 400 })

  const supabase = await createClient()

  const { data: { user }, error: authErr } = await supabase.auth.getUser()
  if (authErr || !user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No studio membership' }, { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const guard = requireFeature(plan, 'payroll')
  if (guard) return guard

  // Join summaries with their parent run's period dates
  const { data, error } = await supabase
    .from('payroll_artist_summary')
    .select(`
      *,
      payroll_runs!inner(period_start, period_end)
    `)
    .eq('artist_id', artistId)
    .eq('studio_id', member.studio_id)
    .order('created_at', { ascending: false })

  if (error) {
    logger.error({ err: error, artistId, studioId: member.studio_id }, 'payroll artist summaries list failed')
    return Response.json({ error: 'Failed to load payroll history' }, { status: 500 })
  }

  // Flatten period dates into the summary row
  const rows = (data ?? []).map((row) => {
    const run = row.payroll_runs as { period_start: string; period_end: string } | null
    return {
      ...row,
      payroll_runs: undefined,
      period_start: run?.period_start ?? '',
      period_end: run?.period_end ?? '',
    }
  })

  return Response.json({ data: rows })
}

