/**
 * generate-tax-form-pdf job handler.
 *
 * Renders a 1099-K PDF via react-pdf, uploads to Supabase Storage,
 * then updates pdf_storage_path and generated_at on the tax_forms row.
 *
 * WORKER-ONLY — react-pdf must never be imported from the Next.js web package.
 */
import React from 'react'
import { renderToBuffer } from '@react-pdf/renderer'
import { createClient } from '@supabase/supabase-js'
import pino from 'pino'
import { TaxForm1099KPdf } from '../lib/pdf/tax-form-1099k'

const logger = pino({ level: process.env['LOG_LEVEL'] ?? 'info' })

function getServiceRoleClient() {
  const url = process.env['NEXT_PUBLIC_SUPABASE_URL'] ?? process.env['SUPABASE_URL']
  const key = process.env['SUPABASE_SERVICE_ROLE_KEY']
  if (!url || !key) throw new Error('Missing Supabase env vars for generate-tax-form-pdf worker')
  return createClient(url, key, {
    auth: { autoRefreshToken: false, persistSession: false },
  })
}

export interface GenerateTaxFormPdfJobData {
  form_id: string
  studio_id: string
}

interface TaxFormRow {
  id: string
  studio_id: string
  artist_id: string
  tax_year: number
  form_type: string
  gross_amount_cents: number
  transaction_count: number
  status: string
  locked_at: string | null
}

interface ArtistTaxInfoRow {
  legal_name: string | null
  tin_last4: string | null
  tin_type: string | null
  address: Record<string, string> | null
}

interface StudioRow {
  name: string
}

interface ArtistRow {
  full_name: string | null
}

export async function handleGenerateTaxFormPdf({ form_id, studio_id }: GenerateTaxFormPdfJobData) {
  const log = logger.child({ handler: 'generate-tax-form-pdf', form_id, studio_id })
  log.info('starting PDF generation')

  const supabase = getServiceRoleClient()

  // Fetch form
  const { data: form, error: formErr } = await supabase
    .from('tax_forms')
    .select('id, studio_id, artist_id, tax_year, form_type, gross_amount_cents, transaction_count, status, locked_at')
    .eq('id', form_id)
    .eq('studio_id', studio_id)
    .single()

  if (formErr || !form) {
    log.error({ err: formErr }, 'tax form not found')
    throw new Error(`Tax form not found: ${form_id}`)
  }

  const typedForm = form as TaxFormRow

  if (typedForm.status === 'voided') {
    log.warn('refusing to generate PDF for voided form')
    throw new Error('Cannot generate PDF for voided form')
  }

  // Fetch studio name
  const { data: studio } = await supabase
    .from('studios')
    .select('name')
    .eq('id', studio_id)
    .single()

  const typedStudio = studio as StudioRow | null

  // Fetch artist name
  const { data: artist } = await supabase
    .from('artists')
    .select('full_name')
    .eq('id', typedForm.artist_id)
    .single()

  const typedArtist = artist as ArtistRow | null

  // Fetch masked tax info (tin_last4, legal_name, address)
  const { data: taxInfo } = await supabase
    .from('artist_tax_info')
    .select('legal_name, tin_last4, tin_type, address')
    .eq('artist_id', typedForm.artist_id)
    .eq('studio_id', studio_id)
    .maybeSingle()

  const typedTaxInfo = taxInfo as ArtistTaxInfoRow | null
  const generatedAt = new Date().toISOString()

  log.info('rendering PDF')
  const pdfBuffer = await renderToBuffer(
    React.createElement(TaxForm1099KPdf, {
      taxYear: typedForm.tax_year,
      studioName: typedStudio?.name ?? 'Studio',
      artistName: typedArtist?.full_name ?? 'Artist',
      legalName: typedTaxInfo?.legal_name ?? null,
      grossAmountCents: typedForm.gross_amount_cents,
      transactionCount: typedForm.transaction_count,
      tinLast4: typedTaxInfo?.tin_last4 ?? null,
      tinType: typedTaxInfo?.tin_type ?? null,
      address: typedTaxInfo?.address ?? null,
      generatedAt,
      formId: form_id,
    })
  )

  const pdfPath = `${studio_id}/${typedForm.tax_year}/${form_id}.pdf`
  log.info({ path: pdfPath }, 'uploading PDF to storage')

  const { error: uploadErr } = await supabase.storage
    .from('tax-forms')
    .upload(pdfPath, pdfBuffer, {
      contentType: 'application/pdf',
      upsert: true,
    })

  if (uploadErr) {
    log.error({ err: uploadErr }, 'PDF upload failed')
    throw uploadErr
  }

  const { error: updateErr } = await supabase
    .from('tax_forms')
    .update({
      pdf_storage_path: pdfPath,
      generated_at: generatedAt,
      status: 'generated',
    })
    .eq('id', form_id)

  if (updateErr) {
    log.error({ err: updateErr }, 'failed to update tax_forms after PDF generation')
    throw updateErr
  }

  log.info({ path: pdfPath }, 'PDF generated and stored successfully')
}

/**
 * send-tax-form job handler.
 *
 * Downloads the generated 1099-K PDF from Supabase Storage, sends it to the
 * artist's email via Resend, then updates sent_at / sent_to_email on tax_forms.
 */
import { createClient } from '@supabase/supabase-js'
import pino from 'pino'

const logger = pino({ level: process.env['LOG_LEVEL'] ?? 'info' })

function getServiceRoleClient() {
  const url = process.env['NEXT_PUBLIC_SUPABASE_URL'] ?? process.env['SUPABASE_URL']
  const key = process.env['SUPABASE_SERVICE_ROLE_KEY']
  if (!url || !key) throw new Error('Missing Supabase env vars for send-tax-form worker')
  return createClient(url, key, {
    auth: { autoRefreshToken: false, persistSession: false },
  })
}

export interface SendTaxFormJobData {
  form_id: string
  studio_id: string
  sent_by: string
}

interface TaxFormRow {
  id: string
  studio_id: string
  artist_id: string
  tax_year: number
  status: string
  pdf_storage_path: string | null
  locked_at: string | null
}

interface ArtistRow {
  full_name: string | null
  email: string | null
}

interface StudioRow {
  name: string
}

export async function handleSendTaxForm({ form_id, studio_id, sent_by }: SendTaxFormJobData) {
  const log = logger.child({ handler: 'send-tax-form', form_id, studio_id, sent_by })
  log.info('starting send-tax-form')

  const supabase = getServiceRoleClient()

  // Fetch form
  const { data: form, error: formErr } = await supabase
    .from('tax_forms')
    .select('id, studio_id, artist_id, tax_year, status, pdf_storage_path, locked_at')
    .eq('id', form_id)
    .eq('studio_id', studio_id)
    .single()

  if (formErr || !form) {
    log.error({ err: formErr }, 'tax form not found')
    throw new Error(`Tax form not found: ${form_id}`)
  }

  const typedForm = form as TaxFormRow

  if (typedForm.status === 'voided') {
    throw new Error('Cannot send a voided form')
  }
  if (!typedForm.pdf_storage_path) {
    throw new Error('PDF must be generated before sending')
  }

  // Fetch artist email
  const { data: artist } = await supabase
    .from('artists')
    .select('full_name, email')
    .eq('id', typedForm.artist_id)
    .single()

  const typedArtist = artist as ArtistRow | null

  if (!typedArtist?.email) {
    throw new Error(`Artist has no email address on file — cannot send 1099-K`)
  }

  // Fetch studio name for email branding
  const { data: studio } = await supabase
    .from('studios')
    .select('name')
    .eq('id', studio_id)
    .single()

  const typedStudio = studio as StudioRow | null

  // Download PDF from storage
  const { data: pdfData, error: downloadErr } = await supabase.storage
    .from('tax-forms')
    .download(typedForm.pdf_storage_path)

  if (downloadErr || !pdfData) {
    log.error({ err: downloadErr }, 'PDF download from storage failed')
    throw downloadErr ?? new Error('PDF not found in storage')
  }

  const pdfBuffer = Buffer.from(await pdfData.arrayBuffer())

  // Send via Resend
  const { Resend } = await import('resend')
  const resend = new Resend(process.env['RESEND_API_KEY'])
  const fromEmail = process.env['RESEND_FROM_EMAIL'] ?? 'notifications@inkos.app'
  const studioName = typedStudio?.name ?? 'Your Studio'
  const artistName = typedArtist.full_name ?? 'Artist'

  const result = await resend.emails.send({
    from: fromEmail,
    to: typedArtist.email,
    subject: `Your ${typedForm.tax_year} Form 1099-K from ${studioName}`,
    html: `
      <p>Hi ${artistName},</p>
      <p>Please find your <strong>Form 1099-K</strong> for tax year <strong>${typedForm.tax_year}</strong> attached.</p>
      <p>This form reports payments you received from <strong>${studioName}</strong> through the InkOS platform.</p>
      <p>Please retain this form for your tax records. If you have questions about the reported amount,
      contact the studio directly.</p>
      <p>— ${studioName}</p>
    `,
    attachments: [
      {
        filename: `1099-K_${artistName.replace(/\s+/g, '_')}_${typedForm.tax_year}.pdf`,
        content: pdfBuffer,
      },
    ],
  })

  if (result.error) {
    log.error({ err: result.error }, 'Resend send failed')
    throw new Error(`Email delivery failed: ${result.error.message}`)
  }

  log.info({ email: typedArtist.email, resendId: result.data?.id }, 'email sent')

  // Update tax_forms: sent_at, sent_to_email, status
  const sentAt = new Date().toISOString()
  const { error: updateErr } = await supabase
    .from('tax_forms')
    .update({
      sent_at: sentAt,
      sent_to_email: typedArtist.email,
      status: 'sent',
    })
    .eq('id', form_id)

  if (updateErr) {
    log.error({ err: updateErr }, 'failed to update tax_forms after send')
    throw updateErr
  }

  log.info({ sentAt, email: typedArtist.email }, 'send-tax-form completed successfully')
}

