// Monthly payroll — 1st of month, 9:00 AM UTC
// Sprint 8: enqueue payroll auto-calculation for studios with auto_payroll enabled
cron.schedule('0 9 1 * *', async () => {
  const log = logger.child({ job: 'monthly-payroll' })
  log.info('cron: enqueueing monthly payroll run')
  try {
    await enqueueMonthlyPayroll()
  } catch (err) {
    log.error({ err }, 'monthly-payroll cron failed')
  }
})

// Yearly 1099-K — January 15, 10:00 AM UTC
// Sprint 8: generate 1099-K drafts for all studios for prior calendar year
cron.schedule('0 10 15 1 *', async () => {
  const log = logger.child({ job: 'yearly-1099k' })
  log.info('cron: enqueueing 1099-K generation for prior year')
  try {
    await enqueueYearly1099K()
  } catch (err) {
    log.error({ err }, 'yearly-1099k cron failed')
  }
})

// ── Sprint 8: Payroll cron helpers ───────────────────────────────────────────

/**
 * Enqueue `generate-payroll` for studios that have auto_payroll = true.
 * Runs on the 1st of every month at 09:00 UTC.
 *
 * Actual run creation and commission aggregation happens in the job handler.
 * This cron just discovers which studios are eligible.
 */
async function enqueueMonthlyPayroll() {
  const log = logger.child({ fn: 'enqueueMonthlyPayroll' })
  const supabase = getServiceRoleClient()

  // Studios with an active subscription (Pro+) are eligible for payroll
  const { data: studios, error } = await supabase
    .from('subscriptions')
    .select('studio_id')
    .eq('status', 'active')
    .in('plan_tier', ['pro', 'studio', 'enterprise'])

  if (error) {
    log.error({ err: error }, 'failed to fetch eligible studios for payroll')
    return
  }
  if (!studios || studios.length === 0) {
    log.info('no eligible studios for monthly payroll')
    return
  }

  const now = new Date()
  const year = now.getFullYear()
  const month = now.getMonth() // 0-indexed — this is the month just starting; calculate prior month
  const prevMonth = month === 0 ? 11 : month - 1
  const prevYear = month === 0 ? year - 1 : year
  const periodStart = new Date(prevYear, prevMonth, 1).toISOString().slice(0, 10)
  const periodEnd = new Date(prevYear, prevMonth + 1, 0).toISOString().slice(0, 10)

  let enqueued = 0
  for (const row of studios as Array<{ studio_id: string }>) {
    try {
      await jobsQueue.add('generate-payroll', {
        studio_id: row.studio_id,
        period_start: periodStart,
        period_end: periodEnd,
      }, { jobId: `payroll-${row.studio_id}-${periodStart}` }) // deduplicate
      enqueued++
    } catch (err) {
      log.error({ err, studioId: row.studio_id }, 'failed to enqueue generate-payroll')
    }
  }
  log.info({ enqueued, periodStart, periodEnd }, 'monthly payroll jobs enqueued')
}

/**
 * Enqueue `generate-1099k` for all active studios for the prior calendar year.
 * Runs January 15 at 10:00 UTC.
 *
 * The generate_1099k RPC is idempotent — 409 on duplicate year is handled gracefully.
 */
async function enqueueYearly1099K() {
  const log = logger.child({ fn: 'enqueueYearly1099K' })
  const supabase = getServiceRoleClient()

  const priorYear = new Date().getFullYear() - 1

  const { data: studios, error } = await supabase
    .from('subscriptions')
    .select('studio_id')
    .eq('status', 'active')
    .in('plan_tier', ['pro', 'studio', 'enterprise'])

  if (error) {
    log.error({ err: error }, 'failed to fetch studios for 1099-K generation')
    return
  }
  if (!studios || studios.length === 0) {
    log.info('no studios eligible for 1099-K generation')
    return
  }

  let enqueued = 0
  for (const row of studios as Array<{ studio_id: string }>) {
    try {
      await jobsQueue.add('generate-1099k', {
        studio_id: row.studio_id,
        tax_year: priorYear,
      }, { jobId: `1099k-${row.studio_id}-${priorYear}` }) // deduplicate
      enqueued++
    } catch (err) {
      log.error({ err, studioId: row.studio_id }, 'failed to enqueue generate-1099k')
    }
  }
  log.info({ enqueued, priorYear }, '1099-K generation jobs enqueued')
}

